from flask import Flask
app = Flask(__name__)
@app.route('/')
def home():
 return """
<!DOCTYPE html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Mi Negocio 6.0</title><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"></head>
<body class="bg-[#FFF8F0] min-h-screen"><div class="max-w-md mx-auto pb-[90px]">
<div class="bg-white p-3 flex justify-between items-center sticky top-0 z-20 shadow-sm"><h1 class="font-black">Mi Negocio</h1><button onclick="tab('config')" class="text-[10px] bg-gray-100 px-3 py-1 rounded-full">Config</button></div>

<div id="p-costos" class="p-3">
<div class="bg-white rounded-[24px] p-4 shadow-sm">
<div class="flex gap-2 mb-2"><button id="bRec" onclick="setTipoCat('recetario')" class="flex-1 py-2.5 rounded-xl text-[11px] font-black bg-black text-white">📖 RECETARIO</button><button id="bCat" onclick="setTipoCat('catalogo')" class="flex-1 py-2.5 rounded-xl text-[11px] font-black bg-gray-100">🛒 CATÁLOGO</button><button onclick="tab('config')" class="text-[9px] px-2">✎</button></div>
<p id="ayudaTipo" class="text-[10px] text-gray-400 mb-3"></p>
<input id="nombre" placeholder="Nombre: Salsa verde / Combo tacos + refresco" class="w-full border-2 p-3 rounded-xl font-bold text-sm">
<textarea id="descripcion" placeholder="Descripción para el catálogo" class="w-full border p-2 rounded-xl text-[11px] mt-2 h-12"></textarea>
<input id="prodImg" type="file" accept="image/*" class="text-[11px] mt-2"><img id="prevImg" class="w-20 h-20 rounded-xl object-cover mt-2 hidden">
<div id="insumos" class="mt-3 space-y-2"></div>
<div class="flex flex-col gap-2 mt-3">
<div class="flex gap-2"><button onclick="addInsumo()" class="flex-1 text-[11px] bg-orange-100 py-2 rounded-full font-bold">+ Ingrediente suelto</button><button id="btnBase" onclick="addInsumoSalsa()" class="flex-1 text-[11px] bg-amber-100 py-2 rounded-full font-bold">+ Del recetario</button></div>
<button id="btnComplemento" onclick="addInsumoCatalogo()" class="hidden text-[11px] bg-blue-100 py-2 rounded-full font-bold">+ Agregar otro producto / Complemento (refresco, postre)</button>
</div>
<div class="mt-3 p-3 bg-gray-900 text-white rounded-xl text-[12px]"><div class="flex justify-between"><span id="lblIng">Costo recetario</span>$<span id="c-ing">0</span></div><div class="flex justify-between text-amber-300"><span>+ Fijos</span>$<span id="c-fijos">0</span></div><div class="flex justify-between font-bold border-t mt-2 pt-2">Costo $<span id="costo">0</span> | Venta $<span id="venta">0</span> <input id="margen" type="number" value="100" class="w-12 text-black rounded text-center text-[11px] ml-2">%</div><div class="mt-2 flex gap-2"><span class="text-[10px] opacity-70">Precio venta manual:</span><input id="ventaManual" type="number" placeholder="Si es combo pon precio final" class="flex-1 text-black rounded px-2 py-1 text-[11px]" oninput="usarManual()"></div></div>
<button id="btnGuardar" onclick="guardar()" class="w-full mt-3 bg-black text-white py-3 rounded-xl font-black text-sm">Guardar en RECETARIO</button><button id="btnCancelarEdit" onclick="cancelarEdit()" class="hidden w-full mt-2 bg-gray-100 py-2 rounded-xl text-[11px]">Cancelar edición</button>
</div><div id="listaInv" class="mt-4"></div>
</div>

<div id="p-vender" class="p-3 hidden"><div id="filtrosCat" class="flex gap-2 overflow-auto pb-2 mb-2"></div><div id="listaVenta" class="grid grid-cols-2 gap-3"></div>
<div class="mt-6 bg-white rounded-[20px] p-4 shadow-xl border"><h3 class="font-bold text-sm">Presupuesto <span id="c-count">0</span></h3><div id="c-items" class="text-[12px] mt-2"></div><select id="selCliente" class="w-full border p-2 rounded-xl text-sm mt-3"></select><div class="flex justify-between font-black text-lg mt-3">Total $<span id="c-total">0</span></div><button onclick="enviarPresupuesto()" class="w-full mt-3 bg-green-500 text-white py-3 rounded-xl font-black text-sm">WhatsApp</button><button onclick="cobrar()" class="w-full mt-2 bg-black text-white py-2 rounded-xl text-sm">Cobrar</button></div></div>

<div id="p-finanzas" class="p-3 hidden">
<div class="bg-[#2D3748] rounded-[20px] p-4 text-white"><div class="flex justify-between"><h2 class="font-black">Finanzas</h2><button onclick="openModalGasto()" class="bg-[#4FD1C5] text-black w-8 h-8 rounded-lg font-black">+</button></div><div class="grid grid-cols-3 gap-2 mt-3 text-center text-[10px]"><div class="bg-white/10 p-2 rounded-xl">HOY $<span id="f-flujoHoy">0</span></div><div class="bg-red-500/80 p-2 rounded-xl">POR PAGAR $<span id="f-porPagar">0</span></div><div class="bg-green-500 p-2 rounded-xl">VENCIDO $<span id="f-vencido">0</span></div></div><div class="mt-3 flex gap-1 overflow-auto"><button onclick="vistaFin='facturas';mostrarFinanzas()" id="vf-facturas" class="text-[10px] bg-white text-black px-3 py-1.5 rounded-full font-bold">Facturas</button><button onclick="vistaFin='proveedores';mostrarFinanzas()" id="vf-proveedores" class="text-[10px] bg-white/20 px-3 py-1.5 rounded-full">Proveedores</button><button onclick="vistaFin='categorias';mostrarFinanzas()" id="vf-categorias" class="text-[10px] bg-white/20 px-3 py-1.5 rounded-full">Cat. gastos</button></div></div>
<div id="view-facturas"><div class="mt-3 bg-white rounded-2xl p-3 shadow-sm"><div class="flex justify-between"><h3 class="font-bold text-[11px]">Calendario</h3><input id="calFecha" type="date" class="text-[11px] border rounded p-1" onchange="mostrarFinanzas()"></div><div id="f-calendario" class="mt-2"></div></div><div class="mt-3 bg-white rounded-2xl p-3 shadow-sm"><div class="flex gap-2 mb-2 overflow-auto text-[10px]"><button onclick="subFin='todos';mostrarFinanzas()" class="bg-gray-900 text-white px-3 py-1 rounded-full">Todos</button><select id="filtroProv" onchange="mostrarFinanzas()" class="border rounded-full px-2 py-1"><option value="todos">Prov</option></select><select id="filtroCatGasto" onchange="mostrarFinanzas()" class="border rounded-full px-2 py-1"><option value="todos">Cat</option></select></div><div id="f-lista"></div></div></div>
<div id="view-proveedores" class="hidden"><div class="mt-3 bg-white rounded-2xl p-4 shadow-sm"><div class="flex gap-2"><input id="provNombre" placeholder="Proveedor" class="flex-1 border p-2 rounded-xl text-sm"><input id="provTel" placeholder="Tel" class="w-20 border p-2 rounded-xl text-sm"><button onclick="addProveedor()" class="bg-black text-white px-3 rounded-xl">+</button></div><div id="listaProveedores" class="mt-3"></div></div></div>
<div id="view-categorias" class="hidden"><div class="mt-3 bg-white rounded-2xl p-4 shadow-sm"><div class="flex gap-2"><input id="catGastoNombre" placeholder="Categoría gasto" class="flex-1 border p-2 rounded-xl text-sm"><button onclick="addCatGasto()" class="bg-black text-white px-3 rounded-xl">+</button></div><div id="listaCatGastos" class="mt-3"></div></div></div>
<div id="modalGasto" class="hidden fixed inset-0 bg-black/60 z-50 flex items-center justify-center p-4"><div class="bg-white w-full max-w-sm rounded-[24px] p-5 max-h-[90vh] overflow-auto"><h3 class="font-black text-sm">Nuevo gasto</h3><select id="g-tipo" class="w-full border-2 p-3 rounded-xl text-sm mt-3 font-bold"><option value="salida">Salida</option><option value="entrada">Entrada</option></select><input id="g-concepto" placeholder="Concepto" class="w-full border p-3 rounded-xl text-sm mt-2"><input id="g-monto" type="number" placeholder="$ Monto" class="w-full border-2 p-3 rounded-xl text-sm mt-2 font-bold"><div class="grid grid-cols-2 gap-2 mt-2"><select id="g-proveedor" class="border p-2 rounded-xl text-sm"></select><select id="g-catGasto" class="border p-2 rounded-xl text-sm"></select></div><input id="g-fecha" type="date" class="w-full border-2 p-3 rounded-xl text-sm mt-3"><div class="flex gap-2 mt-4"><button onclick="document.getElementById('modalGasto').classList.add('hidden')" class="flex-1 bg-gray-100 py-3 rounded-xl">Cancelar</button><button onclick="addFactura()" class="flex-1 bg-black text-white py-3 rounded-xl font-black">Guardar</button></div></div></div>
</div>

<div id="p-clientes" class="p-3 hidden"><div class="bg-white rounded-2xl p-4 shadow-sm"><input id="cliNombre" placeholder="Nombre" class="border p-3 rounded-xl text-sm w-full mb-2"><input id="cliTel" placeholder="WhatsApp" class="border p-3 rounded-xl text-sm w-full mb-2"><input id="cliDir" placeholder="Dirección" class="border p-3 rounded-xl text-sm w-full mb-2"><button onclick="addCliente()" class="bg-black text-white w-full py-3 rounded-xl font-bold text-sm">Guardar</button></div><div id="listaClientes" class="mt-3 space-y-2"></div></div>

<div id="p-config" class="p-3 hidden">
<div class="bg-white rounded-2xl p-4 shadow-sm"><h2 class="font-black text-sm">📖 Recetario / 🛒 Catálogo - Categorías</h2><p class="text-[10px] text-gray-400 mt-1">Recetario = bases que no vendes solas. Catálogo = lo que vendes. Marca cuáles son base.</p><div id="listaCats" class="mt-3 space-y-2"></div><div class="flex gap-2 mt-3"><input id="newCat" placeholder="Nueva: Ej Combos" class="flex-1 border p-2.5 rounded-xl text-sm"><select id="newCatTipo" class="border p-2.5 rounded-xl text-sm"><option value="recetario">Recetario</option><option value="catalogo">Catálogo</option></select><button onclick="addCategoria()" class="bg-black text-white px-4 rounded-xl">+</button></div></div>
<div class="bg-white rounded-2xl p-4 shadow-sm mt-4"><h2 class="font-black text-sm">Gastos fijos para costeo</h2><div id="gastosFijos" class="mt-3 space-y-2"></div><button onclick="addGastoFijo()" class="w-full mt-2 bg-gray-100 py-2 rounded-full text-[11px] font-bold">+ Gasto</button><input id="prodMes" type="number" value="100" class="w-full border-2 p-3 rounded-xl mt-3 font-bold" oninput="calcGastosFijos()"><div class="mt-2 bg-black text-white p-3 rounded-xl text-center font-black">$<span id="cfg-porReceta">0</span> por producto</div></div>
</div>

<div class="fixed bottom-0 left-0 right-0 bg-white border-t flex justify-around py-2 max-w-md mx-auto z-30 text-gray-300">
<button onclick="tab('costos')" id="nav-costos" class="flex flex-col items-center text-black"><i class="fa-solid fa-book"></i><span class="text-[8px] font-bold">Crear</span></button>
<button onclick="tab('vender')" id="nav-vender" class="flex flex-col items-center"><i class="fa-solid fa-store"></i><span class="text-[8px]">Catálogo</span></button>
<button onclick="tab('finanzas')" id="nav-finanzas" class="flex flex-col items-center"><i class="fa-solid fa-chart-line"></i><span class="text-[8px]">Finanzas</span></button>
<button onclick="tab('clientes')" id="nav-clientes" class="flex flex-col items-center"><i class="fa-solid fa-users"></i><span class="text-[8px]">Clientes</span></button>
</div></div>
<script>
let tipoActual='recetario', editId=null, carrito=[], prodImgBase='', filtroTipo='todos', filtroFin='todos', subFin='todos', vistaFin='facturas'; const U=['kg','g','L','ml','galon','pza','cda'];
function baseFactor(u){ if(u=='kg'||u=='L') return 1000; if(u=='galon') return 3785; return 1;}
document.getElementById('prodImg').onchange=e=>{let r=new FileReader(); r.onload=()=>{prodImgBase=r.result; document.getElementById('prevImg').src=r.result; document.getElementById('prevImg').classList.remove('hidden');}; r.readAsDataURL(e.target.files[0]);};
function getCats(){let c=JSON.parse(localStorage.getItem('categoriasV2')||'null'); if(!c ||!c.find(x=>x.grupo)){c=[{id:'recetario',nombre:'Salsas / Bases',grupo:'recetario',esBase:true},{id:'guisados',nombre:'Guisados base',grupo:'recetario',esBase:true},{id:'catalogo',nombre:'Tacos / Platillos',grupo:'catalogo',esBase:false},{id:'combos',nombre:'Combos',grupo:'catalogo',esBase:false}]; localStorage.setItem('categoriasV2',JSON.stringify(c)); localStorage.removeItem('categorias');} return c;}
function saveCats(c){localStorage.setItem('categoriasV2',JSON.stringify(c)); renderCats(); renderCatBotones();}
function renderCats(){let cats=getCats(); let h=''; cats.forEach((cat,i)=>{h+=`<div class="flex gap-2 items-center bg-gray-50 p-2 rounded-xl"><input value="${cat.nombre}" onchange="let cs=getCats(); cs[${i}].nombre=this.value; saveCats(cs);" class="flex-1 bg-transparent font-bold text-sm outline-none"><span class="text-[9px] ${cat.grupo=='recetario'?'bg-amber-200':'bg-black text-white'} px-2 py-0.5 rounded-full">${cat.grupo}</span><button onclick="let cs=getCats(); cs.splice(${i},1); saveCats(cs);" class="text-red-300 px-2">x</button></div>`;}); document.getElementById('listaCats').innerHTML=h;}
function renderCatBotones(){let cats=getCats(); let recs=cats.filter(c=>c.grupo=='recetario'); let catsC=cats.filter(c=>c.grupo=='catalogo'); if(!tipoActual) tipoActual=recs[0]?.id||cats[0]?.id; let hRec='', hCat=''; let all=cats; all.forEach(cat=>{let act=cat.id==tipoActual; let btn=`<button onclick="tipoActual='${cat.id}'; renderCatBotones(); calc();" class="px-3 py-2 rounded-full text-[11px] font-black border ${act?'bg-black text-white':'bg-white'}">${cat.nombre}</button>`; if(cat.grupo=='recetario') hRec+=btn; else hCat+=btn;}); document.getElementById('catBotones').innerHTML=hRec+'<span class="w-full text-[9px] font-bold opacity-30 mt-2">CATÁLOGO</span>'+hCat; let sel=cats.find(c=>c.id==tipoActual); let isRec=sel?.grupo=='recetario'; document.getElementById('bRec').className=isRec?'flex-1 py-2.5 rounded-xl text-[11px] font-black bg-black text-white':'flex-1 py-2.5 rounded-xl text-[11px] font-black bg-gray-100'; document.getElementById('bCat').className=!isRec?'flex-1 py-2.5 rounded-xl text-[11px] font-black bg-black text-white':'flex-1 py-2.5 rounded-xl text-[11px] font-black bg-gray-100'; document.getElementById('ayudaTipo').innerText=isRec?'RECETARIO: Creas salsas y guisados base que luego usas en catálogo. No se vende solo.':'CATÁLOGO: Producto final que vendes. Puede llevar del recetario + complementos (refresco). Con precio de venta final.'; document.getElementById('btnComplemento').classList.toggle('hidden',isRec); document.getElementById('btnBase').innerText=isRec?'+ Ingrediente':' + Del recetario'; document.getElementById('lblIng').innerText=isRec?'Costo ingredientes':'Costo del combo'; let bg=document.getElementById('btnGuardar'); if(bg) bg.innerText=editId?'Actualizar '+sel.nombre:'Guardar en '+ (sel?sel.nombre.toUpperCase():'');}
function setTipoCat(grupo){let cats=getCats().filter(c=>c.grupo==grupo); if(cats.length) tipoActual=cats[0].id; renderCatBotones();}
function addCategoria(){let n=document.getElementById('newCat').value.trim(), g=document.getElementById('newCatTipo').value; if(!n) return; let cats=getCats(); cats.push({id:Date.now().toString(),nombre:n,grupo:g,esBase:g=='recetario'}); document.getElementById('newCat').value=''; saveCats(cats);}
function addInsumo(d={}){let div=document.createElement('div'); div.className='bg-[#FFF8F0] p-2 rounded-xl border text-[11px]'; div.dataset.tipo='ing'; div.innerHTML=`<div class="flex justify-between"><input placeholder="Ingrediente suelto" value="${d.n||''}" class="in-n font-bold text-sm w-full bg-transparent outline-none"><button onclick="this.parentElement.parentElement.remove();calc()" class="text-red-300">x</button></div><div class="grid grid-cols-3 gap-1 mt-1"><input type="number" value="${d.cc||''}" placeholder="Cant compra" class="in-cc border p-2 rounded-lg" oninput="calc()"><select class="in-uc border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uc==x?'selected':''}>${x}</option>`).join('')}</select><input type="number" value="${d.pc||''}" placeholder="$ compra" class="in-pc border p-2 rounded-lg" oninput="calc()"><input type="number" value="${d.cu||''}" placeholder="Uso" class="in-cu border p-2 rounded-lg" oninput="calc()"><select class="in-uu border p-2 rounded-lg" onchange="calc()">${U.map(x=>`<option ${d.uu==x?'selected':''}>${x}</option>`).join('')}</select><div class="p-2 bg-white rounded-lg text-center font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div);}
function addInsumoSalsa(){let cats=getCats(); let bases=cats.filter(c=>c.grupo=='recetario').map(c=>c.id); let salsas=getProd().filter(p=>bases.includes(p.tipo)); if(!salsas.length) return alert('Primero crea algo en RECETARIO'); let div=document.createElement('div'); div.className='bg-amber-50 p-2 rounded-xl border border-amber-200 text-[11px]'; div.dataset.tipo='receta'; div.innerHTML=`<div class="flex justify-between"><span class="font-bold text-amber-800">📖 Del recetario</span><button onclick="this.parentElement.parentElement.remove();calc()" class="text-red-300">x</button></div><div class="flex gap-1 mt-1"><select class="in-salsa border p-2 rounded-lg flex-1" onchange="calc()">${salsas.map(s=>`<option value="${s.id}" data-costo="${s.costo}" data-venta="${s.venta}">${s.nombre} - costo $${s.costo.toFixed(2)}</option>`).join('')}</select><input type="number" value="1" step="0.1" class="in-salsaCant w-16 border p-2 rounded-lg" oninput="calc()"><div class="p-2 bg-white rounded-lg font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div); calc();}
function addInsumoCatalogo(){let cats=getCats(); let catIds=cats.filter(c=>c.grupo=='catalogo').map(c=>c.id); let prods=getProd().filter(p=>catIds.includes(p.tipo) || true); if(!prods.length) return alert('No hay productos'); let div=document.createElement('div'); div.className='bg-blue-50 p-2 rounded-xl border border-blue-200 text-[11px]'; div.dataset.tipo='catalogo'; div.innerHTML=`<div class="flex justify-between"><span class="font-bold text-blue-800">🛒 Complemento / Producto</span><button onclick="this.parentElement.parentElement.remove();calc()" class="text-red-300">x</button></div><div class="flex gap-1 mt-1"><select class="in-salsa border p-2 rounded-lg flex-1" onchange="calc()">${prods.map(s=>`<option value="${s.id}" data-costo="${s.costo}" data-venta="${s.venta}">${s.nombre} - $${s.venta.toFixed(2)}</option>`).join('')}</select><input type="number" value="1" class="in-salsaCant w-16 border p-2 rounded-lg" oninput="calc()"><div class="p-2 bg-white rounded-lg font-bold">$<span class="in-sub">0</span></div></div>`; document.getElementById('insumos').appendChild(div); calc();}
addInsumo({n:'Cebolla',cc:1,uc:'kg',pc:40,cu:150,uu:'g'});
function getProd(){return JSON.parse(localStorage.getItem('productosV2')||'[]');}
function calcGastosFijos(){let total=0; document.querySelectorAll('#gastosFijos > div').forEach(r=>total+=parseFloat(r.querySelector('.gf-m').value)||0); let prodMes=parseFloat(document.getElementById('prodMes').value)||100; localStorage.setItem('prodMes',prodMes); let arr=[]; document.querySelectorAll('#gastosFijos > div').forEach(r=>arr.push({nombre:r.querySelector('.gf-n').value,monto:parseFloat(r.querySelector('.gf-m').value)||0})); localStorage.setItem('gastosFijos',JSON.stringify(arr)); let por=prodMes>0?total/prodMes:0; document.getElementById('cfg-porReceta').innerText=por.toFixed(2); let cf=document.getElementById('c-fijos'); if(cf) cf.innerText=por.toFixed(2); calc();}
function calc(){let tot=0; document.querySelectorAll('#insumos > div').forEach(row=>{if(row.dataset.tipo=='receta' || row.dataset.tipo=='catalogo'){let sel=row.querySelector('.in-salsa'); let costo=parseFloat(sel.options[sel.selectedIndex].dataset.costo)||0; if(row.dataset.tipo=='catalogo') costo=parseFloat(sel.options[sel.selectedIndex].dataset.venta)||costo; let cant=parseFloat(row.querySelector('.in-salsaCant').value)||0; let sub=costo*cant; row.querySelector('.in-sub').innerText=sub.toFixed(2); tot+=sub;}else{let cc=parseFloat(row.querySelector('.in-cc').value)||0, pc=parseFloat(row.querySelector('.in-pc').value)||0, cu=parseFloat(row.querySelector('.in-cu').value)||0, uc=row.querySelector('.in-uc').value, uu=row.querySelector('.in-uu').value; if(!cc||!pc||!cu){row.querySelector('.in-sub').innerText='0'; return;} let cost=(pc/(cc*baseFactor(uc)))*(cu*baseFactor(uu)); if(uc=='pza'||uu=='pza') cost=(pc/cc)*cu; row.querySelector('.in-sub').innerText=cost.toFixed(2); tot+=cost;}}); let ci=document.getElementById('c-ing'); if(ci) ci.innerText=tot.toFixed(2); let gf=parseFloat(document.getElementById('c-fijos')?.innerText||'0'); let costoEl=document.getElementById('costo'); if(costoEl) costoEl.innerText=(tot+gf).toFixed(2); let m=parseFloat(document.getElementById('margen').value)||0; let calcVenta=(tot+gf)*(1+m/100); let manual=document.getElementById('ventaManual').value; let ventaEl=document.getElementById('venta'); if(manual && parseFloat(manual)>0) ventaEl.innerText=parseFloat(manual).toFixed(2); else ventaEl.innerText=calcVenta.toFixed(2);}
function usarManual(){calc();}
document.getElementById('margen').oninput=calc;
function tab(t){['costos','vender','finanzas','clientes','config'].forEach(x=>{let el=document.getElementById('p-'+x); if(el) el.classList.toggle('hidden',x!=t); let nav=document.getElementById('nav-'+x); if(nav){nav.classList.toggle('text-black',x==t);}}); if(t=='vender') mostrarVenta(); if(t=='finanzas') mostrarFinanzas(); if(t=='clientes') mostrarClientes(); if(t=='config') renderCats();}
function getMovs(){return JSON.parse(localStorage.getItem('movs')||'[]');} function getClientes(){return JSON.parse(localStorage.getItem('clientes')||'[]');} function getFacturas(){return JSON.parse(localStorage.getItem('facturas')||'[]');} function getProveedores(){return JSON.parse(localStorage.getItem('proveedores')||'[]');} function getCatGastos(){let c=JSON.parse(localStorage.getItem('catGastos')||'null'); if(!c){c=[{id:'renta',nombre:'Renta'},{id:'luz',nombre:'Luz / Agua'},{id:'insumos',nombre:'Insumos'}]; localStorage.setItem('catGastos',JSON.stringify(c));} return c;}
function guardar(){let nombre=document.getElementById('nombre').value.trim(); if(!nombre) return alert('Nombre'); let desc=document.getElementById('descripcion').value; let costo=parseFloat(document.getElementById('costo').innerText), venta=parseFloat(document.getElementById('venta').innerText); let ingredientes=[]; document.querySelectorAll('#insumos > div').forEach(row=>{if(row.dataset.tipo=='receta' || row.dataset.tipo=='catalogo'){ingredientes.push({tipo:row.dataset.tipo, id:row.querySelector('.in-salsa').value, cant:row.querySelector('.in-salsaCant').value});} else {ingredientes.push({tipo:'ing', n:row.querySelector('.in-n').value, cc:row.querySelector('.in-cc').value, uc:row.querySelector('.in-uc').value, pc:row.querySelector('.in-pc').value, cu:row.querySelector('.in-cu').value, uu:row.querySelector('.in-uu').value});}}); let p=getProd(); if(editId){let idx=p.findIndex(x=>x.id==editId); if(idx>=0){p[idx].nombre=nombre; p[idx].descripcion=desc; p[idx].costo=costo; p[idx].venta=venta; p[idx].tipo=tipoActual; p[idx].img=prodImgBase||p[idx].img; p[idx].ingredientes=ingredientes;}} else {p.push({id:Date.now(),tipo:tipoActual,nombre,descripcion:desc,costo,venta,img:prodImgBase,ingredientes});} localStorage.setItem('productosV2',JSON.stringify(p)); cancelarEdit();}
function editarProd(id){let p=getProd().find(x=>x.id==id); if(!p) return; editId=id; tipoActual=p.tipo; document.getElementById('nombre').value=p.nombre; document.getElementById('descripcion').value=p.descripcion||''; prodImgBase=p.img||''; if(p.img){document.getElementById('prevImg').src=p.img; document.getElementById('prevImg').classList.remove('hidden');} document.getElementById('insumos').innerHTML=''; if(p.ingredientes && p.ingredientes.length){p.ingredientes.forEach(ing=>{if(ing.tipo=='ing'){addInsumo({n:ing.n,cc:ing.cc,uc:ing.uc,pc:ing.pc,cu:ing.cu,uu:ing.uu});} else if(ing.tipo=='receta'){addInsumoSalsa(); let last=document.getElementById('insumos').lastElementChild; last.querySelector('.in-salsa').value=ing.id; last.querySelector('.in-salsaCant').value=ing.cant;} else if(ing.tipo=='catalogo'){addInsumoCatalogo(); let last=document.getElementById('insumos').lastElementChild; last.querySelector('.in-salsa').value=ing.id; last.querySelector('.in-salsaCant').value=ing.cant;}});} else {addInsumo({});} document.getElementById('ventaManual').value=p.venta; tab('costos'); renderCatBotones(); calc(); document.getElementById('btnCancelarEdit').classList.remove('hidden'); window.scrollTo(0,0);}
function cancelarEdit(){editId=null; prodImgBase=''; document.getElementById('nombre').value=''; document.getElementById('descripcion').value=''; document.getElementById('prevImg').classList.add('hidden'); document.getElementById('insumos').innerHTML=''; document.getElementById('ventaManual').value=''; document.getElementById('btnCancelarEdit').classList.add('hidden'); addInsumo({}); calc(); mostrar();}
function mostrar(){let prods=getProd(); let cats=getCats(); let recIds=cats.filter(c=>c.grupo=='recetario').map(c=>c.id); let catIds=cats.filter(c=>c.grupo=='catalogo').map(c=>c.id); let hRec=`<h2 class="font-black text-sm mt-4">📖 Recetario (${prods.filter(p=>recIds.includes(p.tipo)).length})</h2><p class="text-[10px] text-gray-400">Bases que usas para armar catálogo</p>`; let hCat=`<h2 class="font-black text-sm mt-6">🛒 Catálogo (${prods.filter(p=>catIds.includes(p.tipo)).length}) - Precio venta</h2>`; prods.forEach((p,i)=>{let cat=cats.find(c=>c.id==p.tipo); let isRec=recIds.includes(p.tipo); let card=`<div class="bg-white p-2 rounded-xl flex gap-2 shadow-sm mt-2 items-center border ${isRec?'border-amber-200':'border-green-200'}"><span class="text-[8px] ${isRec?'bg-amber-100':'bg-green-500 text-white'} px-2 py-1 rounded-full font-bold">${cat?cat.nombre:p.tipo}</span><img src="${p.img||''}" class="w-10 h-10 rounded object-cover bg-gray-100"><div class="flex-1"><b class="text-[12px]">${p.nombre}</b><br><span class="text-[10px]">Costo $${p.costo.toFixed(2)} → Venta $${p.venta.toFixed(2)}</span></div><button onclick="editarProd(${p.id})" class="bg-blue-50 text-blue-600 px-2 py-1 rounded-full text-[10px] font-bold">Editar</button><button onclick="let pr=getProd(); pr.splice(${i},1); localStorage.setItem('productosV2',JSON.stringify(pr)); mostrar();" class="text-red-300 px-1">X</button></div>`; if(isRec) hRec+=card; else hCat+=card;}); document.getElementById('listaInv').innerHTML=hRec+hCat; mostrarVenta();}
function mostrarVenta(){let prods=getProd(); let cats=getCats(); let filtros=document.getElementById('filtrosCat'); let catalogoIds=cats.filter(c=>c.grupo=='catalogo').map(c=>c.id); if(filtros) filtros.innerHTML=`<button onclick="filtroTipo='todos';mostrarVenta()" class="px-3 py-1 rounded-full text-[10px] ${filtroTipo=='todos'?'bg-black text-white':'bg-white border'}">Todos catálogo</button>`+cats.filter(c=>c.grupo=='catalogo').map(c=>`<button onclick="filtroTipo='${c.id}';mostrarVenta()" class="px-3 py-1 rounded-full text-[10px] ${filtroTipo==c.id?'bg-black text-white':'bg-white border'}">${c.nombre}</button>`).join(''); let prodsVenta=prods.filter(p=>catalogoIds.includes(p.tipo)); if(filtroTipo!='todos') prodsVenta=prodsVenta.filter(p=>p.tipo==filtroTipo); let h=''; prodsVenta.forEach(p=>{let cat=cats.find(c=>c.id==p.tipo); h+=`<div class="bg-white rounded-2xl shadow-sm border overflow-hidden text-left"><button onclick="addCart(${p.id})" class="w-full text-left"><div class="relative"><img src="${p.img||'https://via.placeholder.com/200'}" class="w-full h-24 object-cover"><span class="absolute top-1 left-1 text-[8px] bg-black text-white px-2 py-0.5 rounded-full font-bold">${cat?cat.nombre:''}</span></div><div class="p-2"><b class="text-[11px] line-clamp-1">${p.nombre}</b><p class="text-[11px] text-green-600 font-bold">$${p.venta.toFixed(2)}</p></div></button><div class="px-2 pb-2 flex gap-1"><button onclick="editarProd(${p.id})" class="flex-1 text-[9px] bg-blue-50 py-1 rounded-full">Editar precio</button></div></div>`;}); let lv=document.getElementById('listaVenta'); if(lv) lv.innerHTML=h||'<p class="text-center text-sm text-gray-400 col-span-2">Crea productos en Catálogo para vender</p>'; let cli=getClientes(); let sel=document.getElementById('selCliente'); if(sel) sel.innerHTML='<option value="">Cliente</option>'+cli.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join('');}
function addCart(id){let p=getProd().find(x=>x.id==id); let ex=carrito.find(x=>x.id==id); if(ex) ex.qty++; else carrito.push({...p,qty:1}); renderCart();}
function renderCart(){let t=0,c=0,html=''; carrito.forEach(x=>{t+=x.venta*x.qty; c+=x.qty; html+=`<div class="flex justify-between py-1 text-[12px]"><span>${x.nombre} x${x.qty}</span><span>$${(x.venta*x.qty).toFixed(0)}</span></div>`;}); let ct=document.getElementById('c-total'); if(ct) ct.innerText=t.toFixed(0); let cc=document.getElementById('c-count'); if(cc) cc.innerText=c; let ci=document.getElementById('c-items'); if(ci) ci.innerHTML=html||'Vacío';}
function vaciar(){carrito=[]; renderCart();}
function cobrar(){if(!carrito.length) return; let total=parseFloat(document.getElementById('c-total').innerText); let movs=getMovs(); movs.unshift({tipo:'entrada',concepto:'Venta: '+carrito.map(c=>c.nombre).join(','),monto:total,fecha:new Date().toLocaleDateString()}); localStorage.setItem('movs',JSON.stringify(movs)); vaciar(); tab('finanzas');}
function enviarPresupuesto(){if(!carrito.length) return; let texto=`*PRESUPUESTO*%0A`; carrito.forEach(p=>texto+=`• ${p.nombre} x${p.qty} $${(p.venta*p.qty).toFixed(2)}%0A`); texto+=`*TOTAL $${document.getElementById('c-total').innerText}*`; window.open('https://wa.me/?text='+texto,'_blank');}
function addCliente(){let n=document.getElementById('cliNombre').value, tel=document.getElementById('cliTel').value, dir=document.getElementById('cliDir').value; if(!n) return; let cli=getClientes(); cli.push({id:Date.now().toString(),nombre:n,tel,direccion:dir}); localStorage.setItem('clientes',JSON.stringify(cli)); document.getElementById('cliNombre').value=''; document.getElementById('cliTel').value=''; document.getElementById('cliDir').value=''; mostrarClientes();}
function mostrarClientes(){let cli=getClientes(); let h=''; cli.forEach((c,i)=>h+=`<div class="bg-white p-3 rounded-xl flex justify-between shadow-sm"><div><b class="text-[12px]">${c.nombre}</b><br><span class="text-[10px]">${c.tel} ${c.direccion||''}</span></div><button onclick="let cl=getClientes(); cl.splice(${i},1); localStorage.setItem('clientes',JSON.stringify(cl)); mostrarClientes();" class="text-red-300">X</button></div>`); document.getElementById('listaClientes').innerHTML=h;}
function openModalGasto(){renderSelectsFactura(); document.getElementById('modalGasto').classList.remove('hidden');}
function renderSelectsFactura(){let provs=getProveedores(); let cats=getCatGastos(); let selP=document.getElementById('g-proveedor'); let selC=document.getElementById('g-catGasto'); if(selP) selP.innerHTML='<option value="">Sin proveedor</option>'+provs.map(p=>`<option value="${p.id}">${p.nombre}</option>`).join(''); if(selC) selC.innerHTML='<option value="">Sin categoría</option>'+cats.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join(''); let fp=document.getElementById('filtroProv'); if(fp) fp.innerHTML='<option value="todos">Todos prov.</option>'+provs.map(p=>`<option value="${p.id}">${p.nombre}</option>`).join(''); let fc=document.getElementById('filtroCatGasto'); if(fc) fc.innerHTML='<option value="todos">Todas cat.</option>'+cats.map(c=>`<option value="${c.id}">${c.nombre}</option>`).join('');}
function addFactura(){let concepto=document.getElementById('g-concepto').value.trim(), monto=parseFloat(document.getElementById('g-monto').value), fecha=document.getElementById('g-fecha').value, tipo=document.getElementById('g-tipo').value, provId=document.getElementById('g-proveedor').value, catId=document.getElementById('g-catGasto').value; if(!concepto||!monto||!fecha) return alert('Faltan datos'); let facts=getFacturas(); facts.push({id:Date.now(),concepto,monto,fecha,fechaObj:new Date(fecha+'T00:00:00').getTime(),tipo,proveedorId:provId,catGastoId:catId,estado:'pendiente'}); localStorage.setItem('facturas',JSON.stringify(facts)); document.getElementById('modalGasto').classList.add('hidden'); document.getElementById('g-concepto').value=''; document.getElementById('g-monto').value=''; mostrarFinanzas();}
function addProveedor(){let n=document.getElementById('provNombre').value.trim(), tel=document.getElementById('provTel').value.trim(); if(!n) return alert('Nombre'); let provs=getProveedores(); provs.push({id:Date.now().toString(),nombre:n,tel}); localStorage.setItem('proveedores',JSON.stringify(provs)); document.getElementById('provNombre').value=''; document.getElementById('provTel').value=''; mostrarFinanzas();}
function addCatGasto(){let n=document.getElementById('catGastoNombre').value.trim(); if(!n) return; let cats=getCatGastos(); cats.push({id:Date.now().toString(),nombre:n}); localStorage.setItem('catGastos',JSON.stringify(cats)); document.getElementById('catGastoNombre').value=''; mostrarFinanzas();}
function mostrarFinanzas(){let facts=getFacturas(); let provs=getProveedores(); let catGastos=getCatGastos(); renderSelectsFactura(); let vfF=document.getElementById('view-facturas'), vp=document.getElementById('view-proveedores'), vc=document.getElementById('view-categorias'); if(vfF) vfF.classList.toggle('hidden',vistaFin!='facturas'); if(vp) vp.classList.toggle('hidden',vistaFin!='proveedores'); if(vc) vc.classList.toggle('hidden',vistaFin!='categorias'); if(vistaFin=='proveedores'){let h=''; provs.forEach((p,i)=>{let total=facts.filter(f=>f.proveedorId==p.id && f.estado=='pendiente').reduce((s,f)=>s+f.monto,0); h+=`<div class="flex justify-between items-center bg-gray-50 p-3 rounded-xl mt-2"><div><b class="text-[13px]">${p.nombre}</b><br><span class="text-[10px] text-gray-400">${p.tel||''} • Por pagar: $${total.toFixed(0)}</span></div><button onclick="let pr=getProveedores(); pr.splice(${i},1); localStorage.setItem('proveedores',JSON.stringify(pr)); mostrarFinanzas();" class="text-red-300">x</button></div>`;}); document.getElementById('listaProveedores').innerHTML=h||'<p class="text-[11px] text-gray-400">Sin proveedores</p>';} if(vistaFin=='categorias'){let h=''; catGastos.forEach((c,i)=>{let total=facts.filter(f=>f.catGastoId==c.id).reduce((s,f)=>s+f.monto,0); h+=`<div class="flex justify-between items-center bg-gray-50 p-3 rounded-xl mt-2"><div><b class="text-[13px]">${c.nombre}</b><br><span class="text-[10px] text-gray-400">Gastado: $${total.toFixed(0)}</span></div><button onclick="let cg=getCatGastos(); cg.splice(${i},1); localStorage.setItem('catGastos',JSON.stringify(cg)); mostrarFinanzas();" class="text-red-300">x</button></div>`;}); document.getElementById('listaCatGastos').innerHTML=h;} if(vistaFin!='facturas'){let hoy=new Date(); hoy.setHours(0,0,0,0); let hoyTime=hoy.getTime(); let porPagar=0,vencido=0; facts.forEach(f=>{if(f.estado=='pendiente' && f.tipo=='salida'){porPagar+=f.monto; if(f.fechaObj<hoyTime) vencido+=f.monto;}}); document.getElementById('f-porPagar').innerText=porPagar.toFixed(0); document.getElementById('f-vencido').innerText=vencido.toFixed(0); return;} let movs=getMovs(); let hoy=new Date(); hoy.setHours(0,0,0,0); let hoyTime=hoy.getTime(); let calFecha=document.getElementById('calFecha').value; let porPagar=0,vencido=0,flujoHoy=0; let lista=facts.slice(); if(calFecha){let fTime=new Date(calFecha+'T00:00:00').getTime(); lista=lista.filter(f=>f.fechaObj==fTime);} let fp=document.getElementById('filtroProv').value; if(fp && fp!='todos') lista=lista.filter(f=>f.proveedorId==fp); let fc=document.getElementById('filtroCatGasto').value; if(fc && fc!='todos') lista=lista.filter(f=>f.catGastoId==fc); facts.forEach(f=>{if(f.estado=='pendiente' && f.tipo=='salida'){porPagar+=f.monto; if(f.fechaObj<hoyTime) vencido+=f.monto;}}); document.getElementById('f-porPagar').innerText=porPagar.toFixed(0); document.getElementById('f-vencido').innerText=vencido.toFixed(0); document.getElementById('f-flujoHoy').innerText=flujoHoy.toFixed(0); let h=''; let grouped={}; lista.forEach(f=>{let key=f.fecha; if(!grouped[key]) grouped[key]=[]; grouped[key].push(f);}); Object.keys(grouped).sort().forEach(fecha=>{h+=`<div class="mt-3"><span class="text-[11px] font-bold">${fecha}</span>`; grouped[fecha].forEach(f=>{let prov=provs.find(p=>p.id==f.proveedorId); let cat=catGastos.find(c=>c.id==f.catGastoId); h+=`<div class="flex justify-between py-2 border-b"><div><p class="text-[12px] font-bold">${f.concepto}</p><p class="text-[10px] text-gray-400">${prov?prov.nombre+' • ':''}${cat?cat.nombre:''}</p></div><div class="text-right"><b class="text-[12px]">$${f.monto}</b><br><button onclick="let fs=getFacturas(); let idx=fs.findIndex(x=>x.id==${f.id}); fs[idx].estado=fs[idx].estado=='pendiente'?'pagado':'pendiente'; localStorage.setItem('facturas',JSON.stringify(fs)); mostrarFinanzas();" class="text-[10px] bg-black text-white px-2 rounded-full">${f.estado}</button> <button onclick="let fs=getFacturas(); fs=fs.filter(x=>x.id!=${f.id}); localStorage.setItem('facturas',JSON.stringify(fs)); mostrarFinanzas();" class="text-red-300 text-[10px]">x</button></div></div>`;}); h+=`</div>`;}); document.getElementById('f-lista').innerHTML=h||'<p class="text-center text-[11px] text-gray-400 py-6">Sin facturas</p>'; let calH=''; facts.filter(f=>f.estado=='pendiente').sort((a,b)=>a.fechaObj-b.fechaObj).slice(0,5).forEach(f=>{let diff=Math.ceil((f.fechaObj-hoyTime)/(1000*60*60*24)); let txt=diff<0?`Venció hace ${Math.abs(diff)}d`: diff==0?'Vence hoy':`En ${diff} días`; calH+=`<div class="flex justify-between text-[11px] py-1 border-b"><span>${f.concepto} • ${f.fecha}</span><span class="${diff<0?'text-red-500 font-bold':'text-gray-500'}">${txt}</span></div>`;}); document.getElementById('f-calendario').innerHTML=calH||'<p class="text-[11px] text-gray-400">Sin pendientes</p>';}
function getGF(){return JSON.parse(localStorage.getItem('gastosFijos')||'[]');} function addGastoFijo(d={}){let div=document.createElement('div'); div.className='flex gap-2'; div.innerHTML=`<input value="${d.nombre||''}" placeholder="Concepto" class="gf-n flex-1 border p-2 rounded-xl text-sm"><input type="number" value="${d.monto||''}" placeholder="$" class="gf-m w-24 border p-2 rounded-xl text-sm" oninput="calcGastosFijos()"><button onclick="this.parentElement.remove();calcGastosFijos()" class="text-red-300">x</button>`; document.getElementById('gastosFijos').appendChild(div);}
let sGF=getGF(); if(sGF.length) sGF.forEach(g=>addGastoFijo(g)); else {addGastoFijo({nombre:'Renta',monto:3000});} document.getElementById('prodMes').value=localStorage.getItem('prodMes')||100; let today=new Date().toISOString().split('T')[0]; let gf=document.getElementById('g-fecha'); if(gf) gf.value=today; renderCats(); renderCatBotones(); calcGastosFijos(); calc(); mostrar(); mostrarClientes(); mostrarFinanzas();
</script></body></html>
"""
